        return {
            "status": SKIPPED, "reason": "no_mapped_tests",
            "exit_code": None, "output": "", "tests": [], "mapped_files": [],
            **evidence,
        }
    if len(tests) > MAX_TEST_FILES:
        batches = _ordered_batches(tests)
