        raise ValueError("skip receipt_id is required")
    if receipt.get("coverage_outcome") != "skipped":
        raise ValueError("skip receipt must have coverage_outcome=skipped")
    with _conn() as c:
        c.execute("BEGIN IMMEDIATE")
        existing = c.execute(
            "SELECT * FROM review_receipts WHERE receipt_id=?", (receipt_id,),
        ).fetchone()
        if existing:
            if any(existing[key] != receipt.get(key) for key in stable):
                raise ValueError("skip decision id conflicts with existing provenance")
            return dict(existing)
        _require_bound_task_run_for_review(c, receipt)
        values = {key: receipt.get(key) for key in _REVIEW_RECEIPT_COLUMNS}
        for key in (
            "task_stable_id", "task_snapshot_ref", "prompt_template_start",
            "prompt_template_end", "terminal_operation_id",
        ):
            values[key] = values[key] or ""
        placeholders = ", ".join("?" for _ in _REVIEW_RECEIPT_COLUMNS)
        columns = ", ".join(_REVIEW_RECEIPT_COLUMNS)
        c.execute(
            f"INSERT INTO review_receipts ({columns}) VALUES ({placeholders})",
            tuple(values[key] for key in _REVIEW_RECEIPT_COLUMNS),
        )
        saved = c.execute(
            "SELECT * FROM review_receipts WHERE receipt_id=?", (receipt_id,),
        ).fetchone()
    return dict(saved)


def review_receipt_reserve(receipt: dict) -> dict:
    """Allocate the next artifact round and insert its start receipt atomically."""
    if not isinstance(receipt, dict):
        raise TypeError("review receipt must be a dict")
    artifact_path = str(receipt.get("artifact_path") or "")
    if not artifact_path:
        raise ValueError("review receipt artifact_path is required")
    values = dict(receipt)
    values["round"] = None
    values.setdefault("schema_version", 1)
    values.setdefault("requested_at", datetime.now(timezone.utc).isoformat())
    values.setdefault("status", "requested")
    values.setdefault("failure_code", "")
    values.setdefault("artifact_sha256", "")
    values.setdefault("verdict_value", "")
    values.setdefault("recovery_source", "")
    values.setdefault("author_outcome", "unknown")
    values.setdefault("outcome_source", "unknown")
    values.setdefault("outcome_evidence_ref", "")
    values.setdefault("notification_event_id", "")
    values.setdefault("subject_kind", "unknown")
    values.setdefault("target_sha", "")
    values.setdefault("worker_head", "")
    values.setdefault("production_snapshot_sha256", "")
    values.setdefault("production_paths_json", "[]")
    values.setdefault("coverage_outcome", "unknown")
    values.setdefault("policy_ref", "")
    values.setdefault("decision_actor", "")
    values.setdefault("task_stable_id", "")
    values.setdefault("task_snapshot_ref", "")
    values.setdefault("prompt_template_start", "")
    values.setdefault("prompt_template_end", "")
    values.setdefault("terminal_operation_id", "")
    with _conn() as c:
        c.execute("BEGIN IMMEDIATE")
        _require_bound_task_run_for_review(c, values)
        row = c.execute(
            "SELECT COALESCE(MAX(round), 0) FROM review_receipts WHERE artifact_path=?",
            (artifact_path,),
        ).fetchone()
        values["round"] = int(row[0] or 0) + 1
        placeholders = ", ".join("?" for _ in _REVIEW_RECEIPT_COLUMNS)
        columns = ", ".join(_REVIEW_RECEIPT_COLUMNS)
        c.execute(
            f"INSERT INTO review_receipts ({columns}) VALUES ({placeholders})",
            tuple(values.get(key) for key in _REVIEW_RECEIPT_COLUMNS),
        )
        saved = c.execute(
            "SELECT * FROM review_receipts WHERE receipt_id=?",
            (values["receipt_id"],),
        ).fetchone()
    return dict(saved)

"""#474 — состоявшееся ревью переживает посторонний коммит в main, но не правку прода.

Замер 04.09 на #472: ревью Luna прошло (`review-receipt:01435214-…`, status=completed, rc=0,
coverage_outcome=reviewed), после чего в main приехал посторонний коммит `525684a4`, а воркер
дописал коммиты с тестами. Сырой продовый дифф остался БАЙТ-В-БАЙТ тем же — обе команды дают
одинаковые 167 байт:
    git diff --raw --full-index -z 2268e0fe...2735fcf1 -- app scripts
    git diff --raw --full-index -z 525684a4...598a5848 -- app scripts
— а дайджест сменился `67cf8c11…` → `f8f83743…`, потому что в него входил хеш ЦЕЛИ, и мерж был
отбит «production diff has no snapshot-bound review».

Пара близнецов. Второй важнее первого: он и есть доказательство, что гарантию не сняли, а
только отвязали от постороннего движения main.
"""
import subprocess
